source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                points[grid[r][c]] = (r, c)

    def put(r, c, color):
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = color

    if 1 in points:
        r, c = points[1]
        put(r, c + 1, 5)
        put(r, c + 2, 5)
        put(r - 1, c + 2, 1)
    if 2 in points:
        r, c = points[2]
        put(r, c - 1, 5)
        put(r, c - 2, 5)
        put(r, c - 3, 5)
        put(r, c - 4, 2)
    if 3 in points:
        r, c = points[3]
        for k in range(1, 3):
            put(r + k, c, 5)
        put(r + 3, c, 3)
    if 6 in points:
        r, c = points[6]
        for k in range(1, 6):
            put(r - k, c, 5)
        put(r - 6, c, 6)

    # The 2-ray crossing a vertical 3/6-ray is marked 4, with a diagonal tail.
    if 2 in points:
        r2, c2 = points[2]
        for color in (3, 6):
            if color not in points:
                continue
            rv, cv = points[color]
            if cv == r2 and False:
                pass
            # The horizontal 2 ray lies on its row; vertical ray lies on its column.
            cross_r, cross_c = r2, cv
            if color == 3:
                vmin, vmax = rv, rv + 3
            else:
                vmin, vmax = rv - 6, rv
            hmin, hmax = c2 - 4, c2
            if vmin <= cross_r <= vmax and hmin <= cross_c <= hmax:
                put(cross_r, cross_c, 4)
                k = 1
                while cross_r + k < h and cross_c - k >= 0:
                    put(cross_r + k, cross_c - k, 4)
                    k += 1
    return out
'''
